from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import TranslatablePolicyAgreement

class MultiLangPolicyDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, policy_id):
        # Filter by both pk and user's company tenancy when querying translatable models
        try:
            policy = TranslatablePolicyAgreement.objects.language('all').get(
                pk=policy_id,
                company=request.user.company
            )
        except TranslatablePolicyAgreement.DoesNotExist:
            return Response({'error': 'Policy not found'}, status=status.HTTP_404_NOT_FOUND)

        return Response({
            'policy_id': policy.id,
            'title': policy.title,
            'language_code': policy.language_code,
            'clauses': policy.contract_clauses
        })
